void    d2d_set_get_mask_func   (D2D_Get_Func func) 
{
  ATOMIC(d2d_func.get_mask = func) ;
  
  #if DBG_D2D == 1
    TRACE("\n[D2D Set Get Mask Func]");
  #endif  
}
//--------------------------------------------------------------------------//
Boolean d2d_get_mask (UInt8 code)
{
  if(d2d_func.get_mask)  
    {
      return d2d_func.get_mask(code) ;
    }
  else
    {
      #if DBG_D2D == 1
        TRACE("\n[D2D NO Mask]");
      #endif       
      
      return FALSE ;
         
    }    
}
//--------------------------------------------------------------------------//
Boolean d2d_get_mask_func(UInt8 code)
{  

  return (bitfield_rd(d2d_ena_table.d2d_mask , code , code)) ;
}

